  "attack_progression": [
    {
      "step": 1,
      "tactic": "Execution / Inter-Process Communication — COM Object Instantiation",
      "technique": "T1559.001",
      "what_happened": "At 2027-09-15T08:14:22+0200, Sysmon Event ID 10 (ProcessAccess) fired on WIN-CORP-WS04: a PowerShell process (data.win.eventdata.sourceImage=C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe) opened a handle to mmc.exe with grantedAccess=0x1fffff (PROCESS_ALL_ACCESS). This is the canonical signature of [activator]::CreateInstance() being used to instantiate the MMC20.Application COM object (CLSID 49B2791A-B1AE-4C90-9B8E-E860BA07F889, ProgID MMC20.Application). In normal usage, powershell.exe NEVER opens a process-access handle to mmc.exe — the combination is operationally impossible outside of DCOM lateral-movement tooling (Cobalt Strike dcomexec, Impacket dcomexec, PowerSharpPack).",
      "chain_reason": "Wazuh rule 92741 'MMC20 COM lateral movement' [T1559.001] fired on Sysmon EID 10: data.win.eventdata.sourceImage=*powershell.exe AND data.win.eventdata.targetImage=*mmc.exe AND grantedAccess=0x1fffff. Rule level 15 / critical.",
      "first_seen": "2027-09-15T08:14:22+0200"
    },
    {
      "step": 2,
      "tactic": "Execution / Inter-Process Communication — COM-Spawned Shell",
      "technique": "T1559.001",
      "what_happened": "At 2027-09-15T08:17:44+0200, Sysmon Event ID 1 (ProcessCreate) fired: mmc.exe (C:\\Windows\\System32\\mmc.exe) spawned cmd.exe with commandLine='/c whoami > C:\\Users\\LABUSER~1\\AppData\\Local\\Temp\\com_out_20270915_081744.txt'. The parent-child pair mmc.exe → cmd.exe is an impossible relationship in any legitimate production scenario — mmc.exe is the Microsoft Management Console host and NEVER spawns cmd.exe as a child process except when exploited via DCOM IPC. Wazuh rule 92742 'COM-spawned shell process' fired immediately. The output file path follows the naming convention com_out_<timestamp>.txt in the TEMP directory, matching the canonical MMC20.Application.ExecuteShellCommand() call pattern.",
      "chain_reason": "Wazuh rule 92742 'COM-spawned shell process' [T1559.001] fired on Sysmon EID 1: data.win.eventdata.parentImage=*mmc.exe AND data.win.eventdata.image=*cmd.exe. The commandLine redirects whoami output to a TEMP file. Rule level 15 / critical.",
      "first_seen": "2027-09-15T08:17:44+0200"
    },
    {
      "step": 3,
      "tactic": "Defense Evasion / Collection — FIM Trigger on COM Output File",
      "technique": "T1559.001",
      "what_happened": "At 2027-09-15T08:19:33+0200, Wazuh FIM (File Integrity Monitoring) detected the creation of C:\\Users\\LABUSER~1\\AppData\\Local\\Temp\\com_out_20270915_081744.txt on WIN-CORP-WS04 and logged syscheck.event=added with syscheck.path matching the TEMP directory. Wazuh rule 52103 'FIM: COM output file in TEMP' fired at level 12 / high. The file contains the output of whoami executed through the COM channel — a data-staging artifact that the attacker reads before exfiltration. The 90-second delay between cmd.exe execution (08:17:44) and FIM scan detection (08:19:33) is the expected FIM real-time scan latency. After reading the file, the attacker performed cleanup; the FIM added event is the only persistent artifact.",
      "chain_reason": "Wazuh rule 52103 'FIM: COM output file in TEMP' [T1559.001] fired on syscheck.path containing 'com_out_' AND 'Temp'. Rule level 12 / high.",
      "first_seen": "2027-09-15T08:19:33+0200"
    }
  ],
  "time_window": {"start": "2027-09-15T08:14:22+0200", "end": "2027-09-15T08:19:33+0200"},
